{"CommandLine":"node -e "
const fs = require('fs');
const ExcelJS = require('exceljs');

async function findRows() {
  const filePath = 'C:\\\\Users\\\\lg\\\\Desktop\\\\오늘\\\\(데이터검증팀)실사 DB 취합_전달용_260720_배현명_backup_11847_12346.xlsx';
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.readFile(filePath);
  const sheet = workbook.getWorksheet('기업 정보');

  const targetBiznos = ['6051599850', '6178211451', '6178260307', '7838800705'];
  const matches = [];

  sheet.eachRow((row, rowNumber) => {
    const biznoCell = row.getCell(4).value;
    const bizno = biznoCell ? String(typeof biznoCell === 'object' && biznoCell.text ? biznoCell.text : biznoCell).replace(/[^0-9]/g, '') : '';
    if (targetBiznos.includes(bizno)) {
      matches.push({ rowNumber, author: row.getCell(1).value, company: row.getCell(3).value, bizno });
    }
  });

  console.log('Found matches in backup:', matches);
}
findRows().catch(console.error);
